class TestSet(ATTestSet.TestSet):

    FEATURES = ['ALL']

    def _ck_bind_link(self, setup, dut, misc, role):
        """Resolve `[misc] ck_link_<role>` on THIS bench, bind it, and assert its media.

        Fixed frame — do not edit or delete. Three failures it converts from silent to loud:
          1. an undeclared role: the bench has not agreed to host this test;
          2. `init_portlink()` returning (None, None) for a link the bench does not have —
             a None port later renders as `interface None`, so the run fails looking like a
             SCRIPT defect;
          3. the bound port being the wrong MEDIA. That one cannot be caught offline: media
             belongs to the pluggable, and the CLI accepts `polarity`/`speed 100` on fibre
             where they are meaningless, so the run would report a PRODUCT failure that is
             really a cabling error.
        Raising aborts the suite on purpose: "this bench cannot host this test" is not a
        test result. See ask-ck/functions/pytest-creator/TOPOLOGY-PROFILES.md.
        """
        import ck_media
        ref = misc.get('ck_link_' + role)
        if not ref:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: this .setup declares no "
                "ck_link_%s, so the %s link this test needs is not available here. "
                "See TOPOLOGY-PROFILES.md." % (role, role))
        dev_a, dev_b, _named_port = ck_media.parse_link_ref(ref)
        dut_key = misc.get('ck_role_dut', 'swi_a')
        far_key = dev_b if dev_a == dut_key else dev_a
        if far_key == 'tb':
            # The TESTBOX end of a data link (`ck_link_tb = tb-<dut>:<eth>`): the far
            # object is the testbox itself and its port is an Eth, so the ART shape
            # `(dut.portA, tb.ethA) = setup.init_portlink(dut, tb, type1='port')` applies.
            far = self.tb
            (near_port, far_port) = setup.init_portlink(dut, far, type1='port')
        else:
            far = setup.init_swi(far_key)
            (near_port, far_port) = setup.init_portlink(dut, far, type1='port', type2='port')
        if near_port is None or far_port is None:
            raise RuntimeError(
                "BENCH PROBLEM, not a product defect: ck_link_%s = %r but no unused "
                "matching [portlink] exists between %s and %s." % (role, ref, dut_key, far_key))
        status = dut.cmd('show interface %s status' % near_port.name)
        ok, why = ck_media.assert_role_media(status, near_port.name, role)
        if not ok:
            raise RuntimeError(why)
        self.log('topology: role %r -> %s %s <-> %s %s (%s)' % (
            role, dut_key, near_port.name, far_key, far_port.name, why))
        return near_port, far_port, far

    def init(self, setup):
        # Topology is resolved from the .setup [misc] ROLE CONTRACT at run time, so this
        # script names no device and no port: it binds correctly on any bench that declares
        # the roles it needs, and fails loudly on one that does not. The role names come
        # from TOPOLOGY-PROFILES.md; the bench says what they mean HERE.
        tb = setup.init_tb()
        misc = setup.get_all_misc()
        dutA = setup.init_swi(misc.get('ck_role_dut', 'swi_a'))
        
        stk_a = setup.init_stk('stk_a')
        self.tb = tb
        self.dutA = dutA
        self.stk_a = stk_a
        # The TESTBOX data link (profile `tblink`): the ART shape `(dut.portA, tb.ethA)`.
        # Captures, injected frames and pings happen on `tb.ethA`; `dutA.portA` is the
        # DUT port under test at the other end of that cable.
        (dutA.portA, tb.ethA, _tb) = self._ck_bind_link(setup, dutA, misc, 'tb')
        # The NEIGHBOUR switch (profile `copper`), taken from the far end of the one
        # link the case needs — no second lookup, and deterministic on purpose: this used to
        # be a FILL slot and the model declared links the test never used (T33235 bound 4
        # devices and 2 links while referencing 1 of each). Named `peer`, never `dut`: in
        # ART `dut` is the DUT's own stack handle, and a partner called `dut` made every
        # model read `dut.portA` as the DUT's port (T44297, 2026-09-07).
        (dutA.portPeer, peer_port, peer) = self._ck_bind_link(
            setup, dutA, misc, 'copper')
        peer.portDut = peer_port
        self.peer = peer
        # NOT BOUND: swiSrc, ethLink.
        # A test binds the DUT plus ONE partner (the far end of its one link). These names
        # were only ever inferred from the vocabulary of the selected fragments, which is not
        # evidence the test needs them — and every unused binding becomes a topology demand
        # a bench has to satisfy for nothing. Needing a second partner means declaring a
        # second link role in TOPOLOGY-PROFILES.md, not guessing a device here.

    def configure(self):
        tb = self.tb
        dutA = self.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.stk_a
        # One-time SUITE setup, runs ONCE before all test cases. Config only — no pass/fail.
        # setup: configure an IPv6 address on the DUT interface connected to the test host,
        # create the valid user, second valid user (multi-session) and the account to be
        # disabled later with known passwords/privilege level, and set line vty 0 5 /
        # privilege level 15.

        dutA.mode(')#')

        # Configure the IPv6 address with prefix on the management/transit interface
        # connected to the test host. Adapted from the interface-addressing pattern in
        # ART 1341_limits/library_1341.py lines 609-722; that helper only applies IPv4
        # 'ip address' commands, so the actual 'ipv6 address' command is issued here per
        # the CLI reference instead of being force-fit through the IPv4-only helper.
        if 'port' in portA.name:
            dutA.cmd('interface {}'.format(portA.name))
            dutA.cmd('switchport access vlan 1')
            dutA.cmd('interface vlan1')
        else:
            dutA.cmd('interface {}'.format(portA.name))
        self.ipv6TestAddr = ethA.get_ipv6_addr(10)
        dutA.cmd('ipv6 address {}/64'.format(self.ipv6TestAddr))
        dutA.mode(')#')

        # Create the valid user, second valid user (for multi-session tests) and the
        # account to be disabled later, each with known username/password and privilege
        # level 15
        # ART 1341_limits/library_1341.py lines 329-341
        self.userCredentials = generate_dict_of_usernames_and_passwords(num=3)
        usernameList = list(self.userCredentials.keys())
        self.testUserValid = usernameList[0]
        self.testUserValid2 = usernameList[1]
        self.testUserDisable = usernameList[2]

        dutA.cmd('username {} privilege 15 password {}'.format(
            self.testUserValid, self.userCredentials[self.testUserValid]))
        dutA.cmd('username {} privilege 15 password {}'.format(
            self.testUserValid2, self.userCredentials[self.testUserValid2]))
        dutA.cmd('username {} privilege 15 password {}'.format(
            self.testUserDisable, self.userCredentials[self.testUserDisable]))

        dutA.cmd('line vty 0 5')
        dutA.cmd('privilege level 15')
        dutA.mode('#')

        # ART 1341_limits/library_1341.py lines 261-269
        output = run_show_command(dutA, 'show running-config')
        self.log('Base configuration applied for the IPv6 SSH server suite:')
        self.log(output)
        dutA.mode('#')

    def tear_down(self):
        tb = self.tb
        dutA = self.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.stk_a
        # One-time SUITE cleanup, runs ONCE after all cases. No pass/fail.

        dutA.mode(')#')
        if 'port' in portA.name:
            dutA.cmd('interface vlan1')
        else:
            dutA.cmd('interface {}'.format(portA.name))
        ipv6TestAddr = getattr(self, 'ipv6TestAddr', None)
        if ipv6TestAddr:
            dutA.cmd('no ipv6 address {}/64'.format(ipv6TestAddr))
        dutA.mode(')#')

        for username in (getattr(self, 'testUserValid', None),
                          getattr(self, 'testUserValid2', None),
                          getattr(self, 'testUserDisable', None)):
            if username:
                dutA.cmd('no username {}'.format(username))

        dutA.cmd('line vty 0 5')
        dutA.cmd('no privilege level')
        dutA.mode('#')


class TestCase_1(ATTestCase.TestCase):
    testCaseDesc = "Enable the SSH server on the DUT from Global Configuration (`service ssh` / `ssh server` enable form per the platform) and read the SSH server operational status with `show ssh server`. From the IPv6-capable test host, ping the DUT's global unicast IPv6 address and probe TCP port 22 on that address (e.g. a Scapy TCP SYN to port 22 over IPv6, or a socket connect)."
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = "Enable the SSH server on the DUT from Global Configuration (`service ssh` / `ssh server` enable form per the platform) and read the SSH server operational status with `show ssh server`. From the IPv6-capable test host, ping the DUT's global unicast IPv6 address and probe TCP port 22 on that address (e.g. a Scapy TCP SYN to port 22 over IPv6, or a socket connect).\n"
    testCaseMethod += "Verify: `show ssh server` reports the SSH server as enabled and listening on the standard SSH port; the IPv6 ping to the DUT's global unicast address succeeds; the TCP probe to port 22 over IPv6 is answered (SYN-ACK / connect succeeds), proving an IPv6 listener is present.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # This step presumes the DUT has a global unicast IPv6 address reachable from the
        # test host, and that a hostkey exists so the SSH server can actually start.
        # Index 1 is reserved for the testbox/client address across this suite; the DUT
        # side uses index 2 so this step targets the same address later steps use.
        tb.enable_ipv6(logOwner=self)

        dutA.mode(')#')
        if 'port' in portA.name:
            dutA.cmd('interface vlan1')
        else:
            dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('ipv6 address {}/64'.format(ethA.get_ipv6_addr(2)))
        dutA.mode('#')

        dutA.mode(')#')
        dutA.cmd('crypto key destroy hostkey rsa')
        dutA.cmd('crypto key generate hostkey rsa')
        dutA.mode('#')

    def main(self):
        # legacy 5705_DNS/test-5705.1001.py lines 1067-1153
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log("STEP 1: Enable the SSH server on the DUT from Global Configuration (`service ssh` / `ssh server` enable form per the platform) and read the SSH server operational status with `show ssh server`. From the IPv6-capable test host, ping the DUT's global unicast IPv6 address and probe TCP port 22 on that address (e.g. a Scapy TCP SYN to port 22 over IPv6, or a socket connect).")

        enable_ssh(self, dutA)
        if self.has_failed():
            self.log('OBSERVED: service ssh could not be enabled (missing hostkey), aborting further checks')
            return

        output = run_show_command(dutA, 'show ssh server')
        self.log('OBSERVED: {}'.format(output))

        serverEnabledLine = ''
        portLine = ''
        for line in output.splitlines():
            stripped = line.strip()
            if stripped.startswith('SSH Server'):
                serverEnabledLine = stripped
            elif stripped.startswith('Port'):
                portLine = stripped

        if 'Enabled' in serverEnabledLine:
            self.passed('show ssh server reports {}'.format(serverEnabledLine))
        else:
            self.failed('show ssh server did not report the SSH server as Enabled: {}'.format(serverEnabledLine or output))
            return

        if '22' in portLine:
            self.passed('show ssh server reports {}'.format(portLine))
        else:
            self.failed('show ssh server did not report listening on port 22: {}'.format(portLine or output))
            return

        # Index 2 is the DUT-side global unicast IPv6 address across this suite; index 1
        # is reserved for the testbox/client so the two never collide.
        dutIpv6Addr = ethA.get_ipv6_addr(2)
        pingResult = tb.cmd('ping -6 -c 4 {}'.format(dutIpv6Addr))
        pingOutput = pingResult[0] if isinstance(pingResult, (list, tuple)) else pingResult
        self.log('OBSERVED ping: {}'.format(pingOutput))
        if '0% packet loss' in pingOutput:
            self.passed('IPv6 ping to DUT global unicast address {} succeeded (0% packet loss)'.format(dutIpv6Addr))
        else:
            self.failed('IPv6 ping to DUT global unicast address {} did not succeed: {}'.format(dutIpv6Addr, pingOutput.strip()))
            return

        # Probe at the transport layer only: a bare IPv6 TCP connect/banner read proves a
        # listener is present on port 22 without exercising authentication, which is a
        # separate checkpoint covered by a later step.
        tcpProbeOk = False
        probeDetail = ''
        sock = socket.socket(socket.AF_INET6, socket.SOCK_STREAM)
        sock.settimeout(5)
        try:
            sock.connect((dutIpv6Addr, 22, 0, 0))
            banner = sock.recv(64)
            probeDetail = banner.decode('utf-8', errors='ignore').strip()
            if probeDetail.startswith('SSH-'):
                tcpProbeOk = True
            else:
                tcpProbeOk = True  # connect succeeded (SYN-ACK completed) even if banner read differs
        except Exception as e:
            probeDetail = str(e)
            tcpProbeOk = False
        finally:
            sock.close()

        self.log('OBSERVED TCP probe on port 22: {}'.format(probeDetail))
        if tcpProbeOk:
            self.passed('TCP probe to port 22 over IPv6 was answered on {} ({})'.format(dutIpv6Addr, probeDetail or 'connect succeeded'))
        else:
            self.failed('TCP probe to port 22 over IPv6 was not answered by {}: {}'.format(dutIpv6Addr, probeDetail))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutA.mode(')#')
        dutA.cmd('no service ssh')
        dutA.cmd('crypto key destroy hostkey rsa')

        if 'port' in portA.name:
            dutA.cmd('interface vlan1')
        else:
            dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no ipv6 address {}/64'.format(ethA.get_ipv6_addr(2)))
        dutA.mode('#')

        tb.disable_ipv6(logOwner=self)


class TestCase_2(ATTestCase.TestCase):
    testCaseDesc = "From the test host, open an SSH session to the DUT using the DUT's GLOBAL UNICAST IPv6 address on the standard port with a valid username and password."
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = "From the test host, open an SSH session to the DUT using the DUT's GLOBAL UNICAST IPv6 address on the standard port with a valid username and password.\n"
    testCaseMethod += 'Verify: The TCP connection and SSH key exchange complete and the session reaches the DUT CLI prompt; the client reports no connection error.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition this step presumes: the SSH server must be enabled on the DUT
        # AND the DUT port facing the test host must carry the same global unicast
        # IPv6 address that main() will dial, or the connect attempt fails simply
        # because nothing is listening at that address, not because of the SSH login
        # itself. Each case is self-contained, so both are (re-)established here.
        enable_ssh(self, dutA)
        dutIPv6 = ethA.get_ipv6_addr(2)
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('ipv6 enable')
        dutA.cmd('ipv6 address {}/64'.format(dutIPv6))
        dutA.mode('#')

    def main(self):
        # ART 1348_security/library_1348.py lines 2292-2338
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log("STEP 2: From the test host, open an SSH session to the DUT using the DUT's GLOBAL UNICAST IPv6 address on the standard port with a valid username and password.")

        dutA_ipv6 = ethA.get_ipv6_addr(2)
        self.log('Opening SSH session from the test host to DUT global unicast IPv6 address {} on port 22'.format(dutA_ipv6))
        ssh = connect_via_ssh(self, dutA_ipv6, username='manager', password='friend')

        if ssh is None:
            output = 'No SSH client session established to {}'.format(dutA_ipv6)
            self.log('OBSERVED: {}'.format(output))
            return

        try:
            shell = ssh.invoke_shell()
            output = send_shell_command(shell, 'show system', timeout=15, log_func=self.log)
        except Exception as e:
            output = ''
            self.log('Exception while reading CLI prompt over the SSH session: {}'.format(e))
        finally:
            ssh.close()

        self.log('OBSERVED: {}'.format(output))
        if output and any(prompt in output for prompt in ['#', '>']):
            self.passed('SSH session over IPv6 reached the DUT CLI prompt with no connection error')
        else:
            self.failed('SSH session over IPv6 did not reach a recognisable DUT CLI prompt: {}'.format(output))

        portscan_service_connectivity(self, tcp_ports=[22])

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutIPv6 = ethA.get_ipv6_addr(2)
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no ipv6 address {}/64'.format(dutIPv6))
        dutA.cmd('no ipv6 enable')
        dutA.mode('#')
        dutA.mode(')#')
        dutA.cmd('no service ssh')
        dutA.mode('#')


class TestCase_3(ATTestCase.TestCase):
    testCaseDesc = "From the test host, open an SSH session to the DUT's LINK-LOCAL IPv6 address on the management/transit interface, supplying the client-side scope/zone identifier (`fe80::.../%<host-if>`), with a valid username and password. Obtain the DUT link-local address first from `show ipv6 interface` output on the console."
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = "From the test host, open an SSH session to the DUT's LINK-LOCAL IPv6 address on the management/transit interface, supplying the client-side scope/zone identifier (`fe80::.../%<host-if>`), with a valid username and password. Obtain the DUT link-local address first from `show ipv6 interface` output on the console.\n"
    testCaseMethod += 'Verify: The session establishes and reaches the DUT CLI prompt when the correct scope/zone identifier is supplied.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition: the management/transit interface under test has IPv6 enabled
        # (so it carries a link-local address) and the SSH server is running with
        # default host keys generated, so this step can SSH to that link-local address.
        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('ipv6 enable')
        dutA.mode('#')
        enable_ssh(self, dutA)

    def main(self):
        # ART 1363_ipv6/test-1363.1001.py lines 98-180
        # a link-local IPv6 target with client-side scope/zone identifier, combined with the
        # show ipv6 interface parse pattern from legacy Poll_device_ssh.py's connector.
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log("STEP 3: From the test host, open an SSH session to the DUT's LINK-LOCAL IPv6 address on the management/transit interface, supplying the client-side scope/zone identifier (`fe80::.../%<host-if>`), with a valid username and password. Obtain the DUT link-local address first from `show ipv6 interface` output on the console.")

        dutA.mode('#')
        ipv6_output = dutA.cmd('show ipv6 interface {}'.format(portA.name))
        match = re.search(r'fe80::[0-9a-fA-F:]+', ipv6_output)
        if not match:
            self.log('OBSERVED: {}'.format(ipv6_output))
            self.failed('No link-local IPv6 address found in show ipv6 interface {} output for the management/transit interface; cannot attempt the SSH connection'.format(portA.name))
            return

        link_local = match.group(0)
        zone = ethA.name
        target = '{}%{}'.format(link_local, zone)
        self.log('DUT link-local address obtained from show ipv6 interface {}: {}, using client-side scope/zone id: {}'.format(portA.name, link_local, zone))

        ssh = connect_via_ssh(self, target, username='manager', password='friend')

        if ssh is None:
            output = 'SSH session to {} did not establish'.format(target)
