        loopback_addr = '2001:db8:44:187::1'
        dutA.mode(')#')
        lo_iface_output = dutA.cmd('interface lo')
        loopback_ipv6_output = dutA.cmd('ipv6 address {}/128'.format(loopback_addr))
        dutA.mode('#')
        output = '{}\n{}'.format(lo_iface_output, loopback_ipv6_output)
