        if 'Invalid input' in output or 'nrecognized command' in output or 'oes not exist' in output:
            self.supported = False
            self.log('INFO: {} does not support an IPv6 address on the local loopback interface; step recorded as not-applicable'.format(dutA))
            responsive_output = dutA.cmd('show ssh server')
            if 'Secure Shell Server Configuration' in responsive_output:
                self.passed('DUT CLI remained responsive ({}) after the unsupported loopback IPv6 configuration attempt was refused'.format(responsive_output.splitlines()[0]))
            else:
                self.failed('DUT CLI did not respond cleanly after the unsupported loopback IPv6 configuration attempt')
            return

        dutGlobalAddr = ethA.get_ipv6_addr(2)
