        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        loopback_addr = '2001:db8:44:187::1'
        dutGlobalAddr = ethA.get_ipv6_addr(2)
        tb.cmd('ip -6 route del {}/128 via {} dev {}'.format(loopback_addr, dutGlobalAddr, ethA.name))

        dutA.mode(')#')
        dutA.cmd('interface lo')
        dutA.cmd('no ipv6 address {}/128'.format(loopback_addr))
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no ipv6 address {}/{}'.format(dutGlobalAddr, ethA.ipv6globPrefix))
        dutA.cmd('no ipv6 enable')
