class TestCase_6(ATTestCase.TestCase):
    testCaseDesc = 'Over the IPv6 SSH session issue a representative range of CLI commands including long/multi-line and paged output (e.g. `show running-config`, `show interface`, `show ipv6 interface`), capturing the full output. Issue the identical commands over an IPv4 SSH session (or the serial console) and capture that output.'
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = 'Over the IPv6 SSH session issue a representative range of CLI commands including long/multi-line and paged output (e.g. `show running-config`, `show interface`, `show ipv6 interface`), capturing the full output. Issue the identical commands over an IPv4 SSH session (or the serial console) and capture that output.\n'
    testCaseMethod += 'Verify: The captured outputs are byte-equivalent apart from volatile fields (timestamps, uptime, counters, session/tty identifiers); no truncation mid-line, no corrupted or missing characters, and the last line of each long output is present in the IPv6-session capture.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Establish the precondition this step presumes: an IPv6 (and IPv4) address
        # reachable from the testbox, an SSH host key, the SSH server enabled, and a
        # valid privileged user allowed to log in via SSH.
        dutA.mode(')#')
        dutA.cmd('interface vlan1')
        dutA.cmd('ipv6 address {}/{}'.format(ethA.get_ipv6_addr(2), ethA.ipv6globPrefix))
        dutA.cmd('ip address {}/{}'.format(ethA.get_ipv4_addr(2), ethA.ipv4subnetPrefix))
        dutA.mode('#')
        dutA.mode(')#')
        output = dutA.cmd('crypto key generate hostkey rsa')
        self.log(output)
        output = enable_ssh(self, dutA)
        self.log(output)
        dutA.cmd('user cliuser privilege 15 password sshTestPass1')
        dutA.cmd('ssh server allow-users cliuser')
        dutA.mode('#')

    def main(self):
        # legacy 5049_validation_example/test-5049.3109.py lines 9-57
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 6: Over the IPv6 SSH session issue a representative range of CLI commands including long/multi-line and paged output (e.g. `show running-config`, `show interface`, `show ipv6 interface`), capturing the full output. Issue the identical commands over an IPv4 SSH session (or the serial console) and capture that output.')

        dutIPv6 = ethA.get_ipv6_addr(2)
        sshUser = 'cliuser'
        sshPass = 'sshTestPass1'

        ssh = paramiko.SSHClient()
        ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        try:
            ssh.connect(dutIPv6, username=sshUser, password=sshPass, timeout=15, banner_timeout=30)
        except Exception as e:
            self.failed('Unable to establish an IPv6 SSH session to {}: {}'.format(dutIPv6, e))
            return

        shell = ssh.invoke_shell()
        time.sleep(1)
        while shell.recv_ready():
            try:
                shell.recv(4096)
            except Exception:
                break

        commands = ['show running-config', 'show interface', 'show ipv6 interface']
        ssh_outputs = {}
        for cmd in commands:
            ssh_outputs[cmd] = send_shell_command(shell, cmd, timeout=30, log_func=self.log)

        ssh.close()

        dutA.mode('#')
        console_outputs = {}
        for cmd in commands:
            console_outputs[cmd] = dutA.cmd(cmd)

        output = '\n'.join('{}: {} bytes captured over IPv6 SSH, {} bytes captured on console'.format(
            cmd, len(ssh_outputs[cmd]), len(console_outputs[cmd])) for cmd in commands)
        self.log('OBSERVED: {}'.format(output))

        if not ssh_outputs['show running-config'].strip():
            self.failed('No output was captured for "show running-config" over the IPv6 SSH session')
            return

        if any('--More--' in ssh_outputs[cmd] for cmd in commands):
            self.failed('Captured IPv6 SSH output still contains "--More--" pagination markers: paged output was not fully retrieved')
        else:
            self.passed('No "--More--" pagination artifacts remain in the IPv6 SSH captured output for {}'.format(commands))

        if any('\x00' in ssh_outputs[cmd] or '\ufffd' in ssh_outputs[cmd] for cmd in commands):
            self.failed('Corrupted (NUL or replacement) characters were detected in the IPv6 SSH captured output')
        else:
            self.passed('No corrupted or missing characters detected in the IPv6 SSH captured output')

        rcLines = [l.strip() for l in ssh_outputs['show running-config'].splitlines() if l.strip()]
        if any(l == 'end' for l in rcLines[-4:]):
            self.passed('Last line "end" of the long "show running-config" output is present in the IPv6-session capture')
        else:
            self.failed('Last line "end" of "show running-config" was not found in the IPv6-session capture: capture may be truncated')

        volatilePatterns = [
            r'\d{4}/\d{2}/\d{2}', r'\d{2}:\d{2}:\d{2}', r'days? \d+', r'peak rate',
            r'Time since last state change', r'packets (input|output)', r'bytes (input|output)',
            r'collisions', r'runts', r'giants', r'buffers', r'index \d+ metric',
            r'^line (con|vty)', r'uptime', r'tty'
        ]

        def is_volatile(line):
            for pat in volatilePatterns:
                if re.search(pat, line, re.IGNORECASE):
                    return True
            return False

        def normalize(text, cmdEcho):
            result = []
            for l in text.splitlines():
                l = l.strip()
                if not l:
                    continue
                if is_volatile(l):
                    continue
                if cmdEcho in l:
                    continue
                if l.endswith('#') or l.endswith('>') or '--More--' in l:
                    continue
                result.append(l)
            return result

        for cmd in commands:
            consoleLines = normalize(console_outputs[cmd], cmd)
            sshLines = normalize(ssh_outputs[cmd], cmd)
            missing = [l for l in consoleLines if l not in sshLines]
            if missing:
                self.failed('"{}": {} console line(s) missing/altered beyond volatile fields in the IPv6 SSH capture, e.g. "{}"'.format(
                    cmd, len(missing), missing[0]))
            else:
                self.passed('"{}": IPv6 SSH capture is byte-equivalent to the console capture apart from volatile fields'.format(cmd))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Mirror configure() in `no` form, undoing anything main() left in place.
        dutA.mode(')#')
        dutA.cmd('no ssh server allow-users cliuser')
        dutA.cmd('no user cliuser')
        dutA.cmd('no service ssh')
        dutA.cmd('crypto key destroy hostkey rsa')
        dutA.cmd('interface vlan1')
        dutA.cmd('no ip address {}/{}'.format(ethA.get_ipv4_addr(2), ethA.ipv4subnetPrefix))
        dutA.cmd('no ipv6 address {}/{}'.format(ethA.get_ipv6_addr(2), ethA.ipv6globPrefix))
        dutA.mode('#')


