class TestCase_14(ATTestCase.TestCase):
    testCaseDesc = 'Repeat failed IPv6 SSH authentication attempts for a valid user beyond the configured retry limit to exercise any lockout behaviour, then wait for the configured lockout period to expire and attempt a login with the CORRECT password.'
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = 'Repeat failed IPv6 SSH authentication attempts for a valid user beyond the configured retry limit to exercise any lockout behaviour, then wait for the configured lockout period to expire and attempt a login with the CORRECT password.\n'
    testCaseMethod += 'Verify: Attempts beyond the configured retry limit are refused/locked out as configured (no partial access at any point); after the lockout expires the correct-password login succeeds and reaches the CLI prompt, confirming recovery behaves as configured. Where the platform applies no lockout, record that the retries are simply refused and the correct-password login still succeeds.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Per-case PRECONDITIONS: an IPv6-reachable SSH server on the DUT with one valid
        # user account whose correct/incorrect passwords are known, so main() can drive
        # repeated bad-password attempts followed by a correct-password recovery attempt.
        self.ipv6Prefix = 'fd00:1487:14::'
        self.dutIpv6Addr = '{}1'.format(self.ipv6Prefix)
        self.sshUser = 'lockusr'
        self.sshGoodPw = 'CorrectHorse9!'
        self.sshBadPw = 'WrongPassword1!'
        self.maxAttempts = 6

        tb.enable_ipv6(self)
        ethA.update_ipv6_address_prefix('{}/64'.format(self.ipv6Prefix))
        ethA.up()

        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('ipv6 enable')
        dutA.cmd('ipv6 address {}/64'.format(self.dutIpv6Addr))
        dutA.mode(')#')
        dutA.cmd('crypto key generate hostkey rsa')
        dutA.cmd('user {} privilege 1 password {}'.format(self.sshUser, self.sshGoodPw))
        dutA.cmd('ssh server allow-users {}'.format(self.sshUser))
        output = enable_ssh(self, dutA)
        self.log(output)
        dutA.mode('#')

    def main(self):
        # legacy tools/Validation/IPv6_Scenario/Single_device_test_scripts/netconf_tests.py lines 336-372
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 14: Repeat failed IPv6 SSH authentication attempts for a valid user beyond the configured retry limit to exercise any lockout behaviour, then wait for the configured lockout period to expire and attempt a login with the CORRECT password.')

        sshHost = '[{}]'.format(self.dutIpv6Addr)
        attemptResults = []
        for attempt in range(1, self.maxAttempts + 1):
            granted = False
            pid = pexpect.spawn('ssh -6 -o StrictHostKeyChecking=no {}@{} -p 22'.format(self.sshUser, sshHost))
            try:
                index = pid.expect(['.*assword:', pexpect.EOF, pexpect.TIMEOUT], timeout=15)
                if index == 0:
                    pid.sendline(self.sshBadPw)
                    index2 = pid.expect(['.*assword:', r'\$', '#', pexpect.EOF, pexpect.TIMEOUT], timeout=15)
                    granted = index2 in (1, 2)
            except Exception as e:
                self.log('IPv6 SSH wrong-password attempt {} raised: {}'.format(attempt, e))
            finally:
                pid.close(force=True)
            attemptResults.append((attempt, granted))
            self.log('Wrong-password IPv6 SSH attempt {} of {} for user {}: access granted = {}'.format(
                attempt, self.maxAttempts, self.sshUser, granted))

        logTail = get_show_log(dutA)
        output = 'wrong-password attempts={}, results={}, log tail={}'.format(
            self.maxAttempts, attemptResults, logTail[-500:] if logTail else '')
        self.log('OBSERVED: {}'.format(output))

        anyGranted = any(granted for (_, granted) in attemptResults)
        if not anyGranted:
            self.passed('All {} repeated wrong-password IPv6 SSH attempts for user {} were refused; no partial access was granted at any point'.format(self.maxAttempts, self.sshUser))
        else:
            self.failed('At least one wrong-password IPv6 SSH attempt for user {} was granted access when it should have been refused'.format(self.sshUser))
            return

        # Allow any lockout timer the platform may apply to expire before retrying.
        time.sleep(30)

        ssh = paramiko.SSHClient()
        ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        loginOk = False
        shellOutput = ''
        try:
            ssh.connect(self.dutIpv6Addr, username=self.sshUser, password=self.sshGoodPw, port=22, timeout=20)
            shell = ssh.invoke_shell()
            time.sleep(1)
            shellOutput = send_shell_command(shell, 'show system', log_func=self.log)
            loginOk = True
        except Exception as e:
            self.log('Correct-password IPv6 SSH login exception: {}'.format(e))
        finally:
            ssh.close()

        self.log('OBSERVED: correct-password login connected={}, shell output tail={}'.format(
            loginOk, shellOutput[-300:] if shellOutput else ''))

        reachedPrompt = loginOk and bool(shellOutput) and ('#' in shellOutput or '$' in shellOutput)
        if reachedPrompt:
            self.passed('After the wait period, correct-password IPv6 SSH login for user {} succeeded and reached the CLI prompt, confirming recovery behaves as configured'.format(self.sshUser))
        else:
            self.failed('Correct-password IPv6 SSH login for user {} did not succeed or did not reach a CLI prompt after the wait period'.format(self.sshUser))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Mirror configure(): remove the test user, allow-users entry, ssh server and
        # host key, and the IPv6 addressing added for this step.
        dutA.mode(')#')
        dutA.cmd('no ssh server allow-users {}'.format(self.sshUser))
        dutA.cmd('no user {}'.format(self.sshUser))
        dutA.cmd('no service ssh')
        dutA.cmd('crypto key destroy hostkey rsa')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no ipv6 address {}/64'.format(self.dutIpv6Addr))
        dutA.cmd('no ipv6 enable')
        dutA.mode('#')

        ethA.down()
        tb.disable_ipv6(self)


class TestCase_15(ATTestCase.TestCase):
    testCaseDesc = 'Determine the configured maximum SSH session limit on the DUT (from `show ssh server` / running-config) and open that many concurrent IPv6 SSH sessions from multiple clients/users, issuing a distinct identifying command in each (e.g. `show users`).'
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = 'Determine the configured maximum SSH session limit on the DUT (from `show ssh server` / running-config) and open that many concurrent IPv6 SSH sessions from multiple clients/users, issuing a distinct identifying command in each (e.g. `show users`).\n'
    testCaseMethod += "Verify: All sessions up to the configured maximum authenticate and remain open simultaneously; each session returns its own correct output independently; the DUT's active-session output attributes each session to the correct username and source IPv6 address.\n"

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a

        dutA.mode(')#')
        dutA.cmd('crypto key generate hostkey rsa')
        output = enable_ssh(self, dutA)
        self.log(output)
        output = dutA.cmd('service ssh ipv6')
        self.log(output)

        # Determine the configured maximum SSH session limit from show ssh server
        # (or, failing that, from the configured vty line range in running-config)
        # BEFORE deciding how many users to provision, so the number of sessions we
        # open matches what the device is actually configured to allow.
        dutA.mode('#')
        serverOutput = dutA.cmd('show ssh server')
        self.log(serverOutput)
        match = re.search(r'(?:Max(?:imum)?\s*(?:SSH\s*)?Sessions?|Session\s*Limit)\s*:\s*(\d+)', serverOutput, re.IGNORECASE)
        if match:
            self.numSessions = int(match.group(1))
            self.log('INFO: parsed configured maximum SSH session limit {} from show ssh server'.format(self.numSessions))
        else:
            runningConfigVty = dutA.cmd('show running-config | grep "line vty"')
            self.log(runningConfigVty)
            vtyMatch = re.search(r'line vty (\d+) (\d+)', runningConfigVty)
            if vtyMatch:
                self.numSessions = int(vtyMatch.group(2)) - int(vtyMatch.group(1)) + 1
                self.log('INFO: no explicit session-limit field in show ssh server; derived maximum {} concurrent sessions from the configured vty line range in running-config'.format(self.numSessions))
            else:
                self.numSessions = 5
                self.log('INFO: no explicit session-limit field found in show ssh server or running-config; using the AlliedWare Plus default of 5 concurrent vty sessions (line vty 0 4)')

        self.userDict = generate_dict_of_usernames_and_passwords(num=self.numSessions, usernameLength=8, passwordLength=12)

        dutA.mode(')#')
        for username, password in self.userDict.items():
            dutA.cmd('username {} privilege 1 password {}'.format(username, password))
            dutA.cmd('crypto key generate userkey {} rsa'.format(username))
            dutA.cmd('ssh server allow-users {}'.format(username))
        dutA.mode('#')

    def main(self):
        # ART 1348_security/library_1348.py lines 1937-2013
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 15: Determine the configured maximum SSH session limit on the DUT (from `show ssh server` / running-config) and open that many concurrent IPv6 SSH sessions from multiple clients/users, issuing a distinct identifying command in each (e.g. `show users`).')

        dutA.mode('#')
        allowUsersOutput = dutA.cmd('show ssh server allow-users')
        self.log('OBSERVED: {}'.format(allowUsersOutput))

        configuredUsers = [u for u in self.userDict if u in allowUsersOutput]
        if len(configuredUsers) != self.numSessions:
            self.failed('show ssh server allow-users only lists {} of the {} configured usernames (configured maximum session limit); cannot open the full set of sessions the DUT is configured to allow'.format(len(configuredUsers), self.numSessions))
            return
        else:
            self.passed('All {} configured usernames, matching the configured maximum SSH session limit, are present in show ssh server allow-users'.format(self.numSessions))

        sshServerAddr = ethA.get_ipv6_addr(2)

        sessions = {}
        failedConnects = []
        for username in configuredUsers:
            password = self.userDict[username]
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            try:
                ssh.connect(sshServerAddr, username=username, password=password, timeout=15)
                sourceAddr = ssh.get_transport().sock.getsockname()[0]
                shell = ssh.invoke_shell()
                sessions[username] = (ssh, shell, sourceAddr)
            except Exception as e:
                failedConnects.append('{}: {}'.format(username, e))

        if len(sessions) != self.numSessions:
            self.failed('Only {} of {} concurrent IPv6 SSH sessions (the configured maximum) authenticated and opened; failures: {}'.format(len(sessions), self.numSessions, failedConnects))
            for ssh, shell, sourceAddr in sessions.values():
                shell.close()
                ssh.close()
            return
        else:
            self.passed('All {} concurrent IPv6 SSH sessions, matching the configured maximum session limit, authenticated and remained open simultaneously'.format(self.numSessions))

        perSessionResults = {}
        for username, (ssh, shell, sourceAddr) in sessions.items():
            output = send_shell_command(shell, 'show users', log_func=self.log)
            perSessionResults[username] = output

        mismatched = [u for u, out in perSessionResults.items() if u not in out]
        if mismatched:
            self.failed('Sessions did not return their own correct "show users" output for users: {}'.format(mismatched))
        else:
            self.passed('Each of the {} sessions independently returned its own correct "show users" output identifying its own username'.format(self.numSessions))

        dutA.mode('#')
        activeSessionOutput = dutA.cmd('show ssh')
        self.log('OBSERVED active sessions: {}'.format(activeSessionOutput))

        sessionLines = activeSessionOutput.splitlines()
        attributionOk = []
        attributionFail = []
        for username, (ssh, shell, sourceAddr) in sessions.items():
            userLines = [line for line in sessionLines if username in line]
            if userLines and any(sourceAddr in line for line in userLines):
                attributionOk.append(username)
            else:
                attributionFail.append('{} (expected source {})'.format(username, sourceAddr))

        for ssh, shell, sourceAddr in sessions.values():
            shell.close()
            ssh.close()

        if not attributionFail and len(attributionOk) == self.numSessions:
            self.passed("DUT's show ssh active-session output correctly attributes all {} sessions to their own username and their own client source IPv6 address".format(self.numSessions))
        else:
            self.failed('DUT show ssh active-session output failed to attribute the correct source IPv6 address to username(s): {}'.format(attributionFail))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a

        dutA.mode(')#')
        for username in self.userDict:
            dutA.cmd('no ssh server allow-users {}'.format(username))
            dutA.cmd('crypto key destroy userkey {} rsa'.format(username))
            dutA.cmd('no username {}'.format(username))
        dutA.cmd('no service ssh ipv6')
        dutA.cmd('no service ssh')
        dutA.cmd('crypto key destroy hostkey rsa')
        dutA.mode('#')


class TestCase_16(ATTestCase.TestCase):
    testCaseDesc = 'With the maximum number of IPv6 SSH sessions already established, attempt one further IPv6 SSH connection from the client, then issue a command in each pre-existing session.'
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = 'With the maximum number of IPv6 SSH sessions already established, attempt one further IPv6 SSH connection from the client, then issue a command in each pre-existing session.\n'
    testCaseMethod += 'Verify: The extra attempt is refused or queued according to the product design (connection closed/refused rather than granted a shell beyond the limit), and every pre-existing session still returns correct command output and remains usable.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition: SSH server enabled over IPv6 with a host key and a login-capable
        # user this step's client sessions will authenticate as.
        self.test_user = 'ipv6ssh'
        self.test_pass = 'ipv6pass123'
        self.log(output)
        output = enable_ssh(self, dutA)
        dutA.mode(')#')
        dutA.cmd('username {} privilege 15 password {}'.format(self.test_user, self.test_pass))
        dutA.cmd('ssh server allow-users {}'.format(self.test_user))
        dutA.mode('#')

    def main(self):
        # ART 6000_link_check/library_6000.py lines 56-70
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 16: With the maximum number of IPv6 SSH sessions already established, attempt one further IPv6 SSH connection from the client, then issue a command in each pre-existing session.')

        dutIpv6 = ethA.get_ipv6_addr(2)
        maxAttempts = 20  # safety cap; any real per-platform session limit is expected well inside this
        sshConnections = []
        extraRefused = False
        extraOutput = ''

        for attempt in range(1, maxAttempts + 1):
            ssh = paramiko.SSHClient()
            ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
            try:
                ssh.connect(dutIpv6, username=self.test_user, password=self.test_pass, timeout=10, banner_timeout=15)
            except Exception as e:
                extraOutput = str(e)
                extraRefused = True
                break
            else:
                sshConnections.append(ssh)

        sessionsEstablished = len(sshConnections)
        output = '{} concurrent IPv6 SSH sessions accepted; further attempt was {}'.format(
            sessionsEstablished,
            'refused/closed: {}'.format(extraOutput) if extraRefused else
            'also granted (no refusal seen within {} attempts)'.format(maxAttempts))
        self.log('OBSERVED: {}'.format(output))

        if sessionsEstablished == 0:
            self.failed('No IPv6 SSH sessions could be established at all; cannot exercise the concurrent-session limit')
            return

        if extraRefused:
            self.passed('Extra IPv6 SSH connection attempt beyond the {} already-established sessions was refused/closed ({})'.format(
                sessionsEstablished, extraOutput))
        else:
            self.failed('Extra IPv6 SSH connection attempt was granted a working session instead of being refused/queued after {} sessions were already open'.format(
                sessionsEstablished))

        allSessionsUsable = True
        for idx, ssh in enumerate(sshConnections):
            try:
                (stdin, stdout, stderr) = ssh.exec_command('show ssh server')
                cmdOutput = stdout.read().decode()
            except Exception as e:
                allSessionsUsable = False
                self.log('Pre-existing session {} failed to run command: {}'.format(idx + 1, e))
                continue
            if 'SSH Server' in cmdOutput and 'Enabled' in cmdOutput:
                self.log('Pre-existing session {} returned correct show ssh server output'.format(idx + 1))
            else:
                allSessionsUsable = False
                self.log('Pre-existing session {} returned unexpected output: {}'.format(idx + 1, cmdOutput))

        if allSessionsUsable:
            self.passed('All {} pre-existing IPv6 SSH sessions returned correct command output and remained usable after the extra attempt'.format(
                sessionsEstablished))
        else:
            self.failed('At least one pre-existing IPv6 SSH session failed to return correct command output after the extra connection attempt')

        for ssh in sshConnections:
            ssh.close()

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutA.mode(')#')
        dutA.cmd('no ssh server allow-users {}'.format(self.test_user))
        dutA.cmd('no username {}'.format(self.test_user))
        dutA.cmd('crypto key destroy hostkey rsa')
        dutA.cmd('no service ssh')
        dutA.mode('#')


