        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 22: From the client, attempt an IPv6 SSH connection to a syntactically valid but UNREACHABLE IPv6 destination address (an address not configured on the DUT and not routed).')

        baselineLog = get_show_log(dutA)

        unreachableAddr = '2001:db8:dead:beef::9999'
