class TestCase_26(ATTestCase.TestCase):
    testCaseDesc = 'After exercising session establishment, successful and failed authentication, administrative session termination and SSH server enable/disable transitions, read the DUT log from the console (`show log`) and filter for SSH-related entries.'
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = 'After exercising session establishment, successful and failed authentication, administrative session termination and SSH server enable/disable transitions, read the DUT log from the console (`show log`) and filter for SSH-related entries.\n'
    testCaseMethod += 'Verify: The log contains entries for IPv6 SSH session establishment, authentication success, authentication failure, the administrative session termination, and each SSH server enable and disable transition; each entry carries a plausible, monotonically increasing timestamp and, for session events, the correct source IPv6 address of the client.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a

        self.ssh_user = 'logtestuser'
        self.ssh_password = 'LogTestPw1'

        dutA.mode(')#')
        dutA.cmd('crypto key generate hostkey rsa')
        enable_ssh(self, dutA)
        dutA.mode(')#')
        dutA.cmd('username {} privilege 1 password {}'.format(self.ssh_user, self.ssh_password))
        dutA.cmd('ssh server allow-users {}'.format(self.ssh_user))
        dutA.mode('#')

    def main(self):
        # ART 1348_security/library_1348.py lines 145-149
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 26: After exercising session establishment, successful and failed authentication, administrative session termination and SSH server enable/disable transitions, read the DUT log from the console (`show log`) and filter for SSH-related entries.')

        dutTargetV6 = ethA.get_ipv6_addr(2)
        clientV6 = ethA.get_ipv6_addr(1)

        dutA.mode('#')
        baselineLog = get_show_log(dutA)

        # 1. Session establishment + successful authentication (create_ssh_swi_object session factory)
        sshControlSwi = []
        create_ssh_swi_object(self, dutA, sshControlSwi)
        if sshControlSwi:
            sshSwi = sshControlSwi[0]
            self.log('Established SSH-connected session object for {}'.format(dutA))
            try:
                sshSwi.cmd('show version')
            except Exception as e:
                self.log('SSH session object command failed: {}'.format(e))

        # Confirmed successful IPv6 SSH connection with valid credentials
        ssh = connect_via_ssh(self, dutTargetV6, self.ssh_user, self.ssh_password)
        if ssh is not None:
            shell = ssh.invoke_shell()
            send_shell_command(shell, 'show version', log_func=self.log)
            time.sleep(1)
            shell.close()
            ssh.close()
        time.sleep(2)

        # 2. Failed authentication - wrong password for a valid user
        fail_ssh_attempt(self, dutA, self.ssh_user, 'WrongPassword999')
        time.sleep(2)

        # 2b. Failed authentication - a username unknown on the DUT
        unknownDevice = [dutTargetV6, dutA.name if hasattr(dutA, 'name') else 'dutA', False]
        try:
            unknownDevice = unconfigured_netconf_user_get_request_test(unknownDevice)
            self.log('Unknown-user authentication attempt result: {}'.format(unknownDevice[-1] if len(unknownDevice) > 2 else unknownDevice))
        except Exception as e:
            self.log('Unknown-user authentication helper raised: {}'.format(e))
        time.sleep(2)

        # 3. Administrative session termination: open a session then kill it from the DUT console
        ssh2 = connect_via_ssh(self, dutTargetV6, self.ssh_user, self.ssh_password)
        if ssh2 is not None:
            shell2 = ssh2.invoke_shell()
            send_shell_command(shell2, 'show version', log_func=self.log)
            dutA.mode(')#')
            dutA.cmd('no service ssh')
            time.sleep(2)
            try:
                shell2.close()
                ssh2.close()
            except Exception:
                pass

        # 4. SSH server enable/disable transitions
        enable_ssh(self, dutA)
        time.sleep(2)
        dutA.mode(')#')
        dutA.cmd('no service ssh')
        time.sleep(2)
        enable_ssh(self, dutA)
        time.sleep(2)

        dutA.mode('#')
        output = get_show_log(dutA)
        self.log('OBSERVED: {}'.format(output))

        newEntries = compare_logs(baselineLog, output)
        sshLines = [l for l in newEntries if 'SSH' in l.upper()]

        if not sshLines:
            self.failed('No SSH-related entries found in show log after exercising session, authentication, termination and enable/disable events')
            return
        else:
            self.passed('SSH-related log entries captured after the exercised events ({} lines)'.format(len(sshLines)))

        establishText = [l for l in sshLines if 'connect' in l.lower() or 'session' in l.lower() or 'stablish' in l.lower()]
        if establishText:
            self.passed('SSH session establishment logged: {}'.format(establishText[0]))
        else:
            self.failed('No SSH session establishment entry found in log')

        successText = [l for l in sshLines if 'accept' in l.lower() or 'success' in l.lower()]
        if successText:
            self.passed('SSH authentication success logged: {}'.format(successText[0]))
        else:
            self.failed('No SSH authentication success entry found in log')

        failText = [l for l in sshLines if 'fail' in l.lower() or 'invalid' in l.lower() or 'denied' in l.lower() or 'refused' in l.lower()]
        if failText:
            self.passed('SSH authentication failure logged: {}'.format(failText[0]))
        else:
            self.failed('No SSH authentication failure entry found in log')

        termText = [l for l in sshLines if 'disconnect' in l.lower() or 'closed' in l.lower() or 'terminat' in l.lower()]
        if termText:
            self.passed('SSH administrative session termination logged: {}'.format(termText[0]))
        else:
            self.failed('No SSH administrative session termination entry found in log')

        enableText = [l for l in sshLines if 'enable' in l.lower() and 'ssh' in l.lower()]
        disableText = [l for l in sshLines if 'disable' in l.lower() and 'ssh' in l.lower()]
        if enableText and disableText:
            self.passed('SSH server enable and disable transitions both logged')
        else:
            self.failed('SSH server enable/disable transition entries missing: enable found={}, disable found={}'.format(bool(enableText), bool(disableText)))

        timestamps = []
        for line in sshLines:
            parts = line.split()
            if len(parts) >= 4:
                candidate = ' '.join(parts[:4])
                try:
                    timestamps.append(datetime.strptime(candidate, '%Y %b %d %H:%M:%S'))
                except ValueError:
                    pass

        monotonic = all(timestamps[i] <= timestamps[i + 1] for i in range(len(timestamps) - 1)) if len(timestamps) > 1 else False
        if timestamps and (len(timestamps) == 1 or monotonic):
            self.passed('SSH log entries carry plausible, monotonically increasing timestamps ({} parsed)'.format(len(timestamps)))
        else:
            self.failed('SSH log entry timestamps missing or not monotonically increasing: {}'.format(timestamps))

        sessionLines = [l for l in sshLines if clientV6 in l]
        if sessionLines:
            self.passed('Session-related SSH log entries carry the correct client source IPv6 address {}'.format(clientV6))
        else:
            self.failed('No SSH session log entry found containing the expected client source IPv6 address {}'.format(clientV6))

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a

        dutA.mode(')#')
        dutA.cmd('no ssh server allow-users {}'.format(self.ssh_user))
        dutA.cmd('no username {}'.format(self.ssh_user))
        dutA.cmd('no service ssh')
        dutA.cmd('crypto key destroy hostkey rsa')
        dutA.mode('#')


class TestCase_27(ATTestCase.TestCase):
    testCaseDesc = 'With the SSH server enabled, the IPv6 listener active and the allow/deny user lists populated, save the configuration on the DUT (`copy running-config startup-config` / `write`), then restart the device and wait for it to boot. After boot, read `show ssh server`, the SSH allow/deny user configuration and `show ipv6 interface`, then attempt an IPv6 SSH login as an allowed user and as a denied user.'
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = 'With the SSH server enabled, the IPv6 listener active and the allow/deny user lists populated, save the configuration on the DUT (`copy running-config startup-config` / `write`), then restart the device and wait for it to boot. After boot, read `show ssh server`, the SSH allow/deny user configuration and `show ipv6 interface`, then attempt an IPv6 SSH login as an allowed user and as a denied user.\n'
    testCaseMethod += 'Verify: After restart the SSH server reports enabled, the management/transit interface still holds its IPv6 address, the allow and deny user lists match what was saved, the IPv6 TCP port 22 listener is present again, the allowed user logs in successfully over IPv6 and the denied user is still rejected — i.e. behaviour matches pre-restart.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Per-case PRECONDITIONS: the device state this step presumes, config only — no
        # pass/fail (main() verifies; tear_down() mirrors this in `no` form). Runs after
        # TestSet.configure() and after the previous case's tear_down(), so nothing another
        # case set up is still in effect here.
        self.allowed_user = 'sshallow27'
        self.allowed_pass = 'AllowPass27x'
        self.denied_user = 'sshdeny27'
        self.denied_pass = 'DenyPass27x'

        ethA.update_ipv6_address_prefix('2001:db8:44187:27::/64')
        self.dut_ipv6_addr = ethA.get_ipv6_addr(1)

        dutA.mode(')#')
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('ipv6 enable')
        dutA.cmd('ipv6 address {}/64'.format(self.dut_ipv6_addr))
        dutA.mode(')#')
        dutA.cmd('username {} privilege 1 password {}'.format(self.allowed_user, self.allowed_pass))
        dutA.cmd('username {} privilege 1 password {}'.format(self.denied_user, self.denied_pass))
        dutA.cmd('ssh server allow-users {}'.format(self.allowed_user))
        dutA.cmd('ssh server deny-users {}'.format(self.denied_user))
        dutA.mode('#')
        output = enable_ssh(self, dutA)
        self.log(output)

    def main(self):
        # legacy 5049_validation_example/test-5049.3109.py lines 60-125
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log('STEP 27: With the SSH server enabled, the IPv6 listener active and the allow/deny user lists populated, save the configuration on the DUT (`copy running-config startup-config` / `write`), then restart the device and wait for it to boot. After boot, read `show ssh server`, the SSH allow/deny user configuration and `show ipv6 interface`, then attempt an IPv6 SSH login as an allowed user and as a denied user.')

        dutA.mode('#')
        preRebootLog = get_show_log(dutA)
        saveOutput = dutA.cmd('write')
        self.log('OBSERVED: save output = {}'.format(saveOutput))

        self.log('Rebooting DUT to confirm SSH server / IPv6 / allow-deny configuration persists across reload')
        dutA.cmd('reboot', log=False)
        time.sleep(60)

        rebooted = False
        timeOutAt = time.time() + 300
        verOut = ''
        while time.time() < timeOutAt:
            try:
                dutA.mode('#')
                verOut = dutA.cmd('show version')
                if verOut and 'awplus' in verOut.lower():
                    rebooted = True
                    break
            except Exception:
                pass
            time.sleep(15)

        if not rebooted:
            self.failed('DUT did not respond with show version output within 300s after reboot - device did not come back up')
            return
        self.passed('DUT responded to show version after reboot')

        postRebootLog = get_show_log(dutA)
        newLogEntries = compare_logs(preRebootLog, postRebootLog)
        self.log('OBSERVED: new log entries since before reboot: {}'.format(newLogEntries))

        sshServerOutput = run_show_command(dutA, 'show ssh server')
        self.log('OBSERVED: show ssh server = {}'.format(sshServerOutput))
        sshEnabledOk = ('SSH Server' in sshServerOutput and 'Enabled' in sshServerOutput)
        if sshEnabledOk:
            self.passed('show ssh server reports SSH Server Enabled after restart')
        else:
            self.failed('show ssh server does not report Enabled after restart: {}'.format(sshServerOutput))

        runConfig = run_show_command(dutA, 'show running-config')
        allowLine = 'ssh server allow-users {}'.format(self.allowed_user)
        denyLine = 'ssh server deny-users {}'.format(self.denied_user)
        allowDenyOk = (allowLine in runConfig and denyLine in runConfig)
        if allowDenyOk:
            self.passed('Allow-users and deny-users configuration persisted across restart ({} / {})'.format(allowLine, denyLine))
        else:
            self.failed('Allow/deny user configuration missing from running-config after restart')

        ipv6Output = run_show_command(dutA, 'show ipv6 interface {}'.format(portA.name))
        self.log('OBSERVED: show ipv6 interface {} = {}'.format(portA.name, ipv6Output))
        ipv6Ok = (self.dut_ipv6_addr in ipv6Output)
        if ipv6Ok:
            self.passed('{} still holds IPv6 address {} after restart'.format(portA.name, self.dut_ipv6_addr))
        else:
            self.failed('{} does not report expected IPv6 address {} after restart: {}'.format(portA.name, self.dut_ipv6_addr, ipv6Output))

        scanResult = portscan_service_connectivity(self, tcp_ports=[22])
        port22Ok = False
        if scanResult:
            for scan_key, scan_data in scanResult.items():
                for ip_addr, host_data in scan_data.items():
                    if ':' in ip_addr and 'tcp' in host_data and 22 in host_data['tcp']:
                        if host_data['tcp'][22].get('state') == 'open':
                            port22Ok = True
        if port22Ok:
            self.passed('IPv6 TCP port 22 (SSH) listener is open again after restart')
        else:
            self.failed('IPv6 TCP port 22 (SSH) listener was not detected as open after restart')

        allowedSsh = connect_via_ssh(self, self.dut_ipv6_addr, username=self.allowed_user, password=self.allowed_pass, expect_failure=False)
        allowedLoginOk = allowedSsh is not None
        if allowedSsh:
            allowedSsh.close()

        deniedSsh = connect_via_ssh(self, self.dut_ipv6_addr, username=self.denied_user, password=self.denied_pass, expect_failure=True)
        deniedLoginBlockedOk = (deniedSsh is None)
        if deniedSsh:
            deniedSsh.close()
        if deniedLoginBlockedOk:
            self.passed('Denied user {} was correctly refused SSH login over IPv6 after restart (no session returned)'.format(self.denied_user))
        else:
            self.failed('Denied user {} unexpectedly obtained an SSH session over IPv6 after restart'.format(self.denied_user))

        monitor_logs_for_continued_change(self, dutA, minutes=1)

        if rebooted and sshEnabledOk and allowDenyOk and ipv6Ok and port22Ok and allowedLoginOk and deniedLoginBlockedOk:
            self.passed('After restart the SSH server reports enabled, the management/transit interface still holds its IPv6 address, the allow and deny user lists match what was saved, the IPv6 TCP port 22 listener is present again, the allowed user logs in successfully over IPv6 and the denied user is still rejected — i.e. behaviour matches pre-restart.')
        else:
            self.failed('After restart the SSH server reports enabled, the management/transit interface still holds its IPv6 address, the allow and deny user lists match what was saved, the IPv6 TCP port 22 listener is present again, the allowed user logs in successfully over IPv6 and the denied user is still rejected — i.e. behaviour matches pre-restart.')

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Per-case cleanup so the next case starts clean: undo configure() and anything
        # main() changed, command for command in `no` form (the ART mirror). No pass/fail.
        dutA.mode(')#')
        dutA.cmd('no ssh server allow-users {}'.format(self.allowed_user))
        dutA.cmd('no ssh server deny-users {}'.format(self.denied_user))
        dutA.cmd('no username {}'.format(self.allowed_user))
        dutA.cmd('no username {}'.format(self.denied_user))
        dutA.cmd('interface {}'.format(portA.name))
        dutA.cmd('no ipv6 address {}/64'.format(self.dut_ipv6_addr))
        dutA.cmd('no ipv6 enable')
        dutA.mode(')#')
        dutA.cmd('no service ssh')
        dutA.mode('#')
        dutA.cmd('write')


class TestCase_28(ATTestCase.TestCase):
    testCaseDesc = "Record baseline DUT resource usage from the console (`show memory`, `show users`, and the platform's process/file-descriptor or system status output), then run many repeated cycles (e.g. 100) of: open an IPv6 SSH session, authenticate (mixing valid logins with deliberately failed ones), execute a CLI command, and disconnect. Re-read the same resource outputs after the final cycle."
    testCaseRef = 'AWPTCM-T44187'
    testCaseMethod  = "Record baseline DUT resource usage from the console (`show memory`, `show users`, and the platform's process/file-descriptor or system status output), then run many repeated cycles (e.g. 100) of: open an IPv6 SSH session, authenticate (mixing valid logins with deliberately failed ones), execute a CLI command, and disconnect. Re-read the same resource outputs after the final cycle.\n"
    testCaseMethod += 'Verify: Every valid cycle establishes, authenticates and returns correct command output throughout the run (including the final cycles); failed authentications are rejected without granting access; after the last cycle the active-session list returns to its baseline (no orphaned sessions), memory and file-descriptor/process usage show no monotonic accumulation versus the baseline, `show log` contains no exception traces or crash records, and the DUT responds to CLI at normal speed.\n'

    def configure(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        # Precondition: DUT reachable over IPv6 from tb, SSH server enabled, one
        # valid user account with a userkey, allowed through ssh server allow-users.
        dutA.mode(')#')
        dutA.cmd('interface vlan1')
        dutA.cmd('ipv6 address {}/{}'.format(tb.ethA.get_ipv6_addr(2), tb.ethA.ipv6globPrefix))
        dutA.mode('#')
        dutA.mode(')#')
        dutA.cmd('crypto key generate hostkey rsa')
        dutA.cmd('user sshuser privilege 15 password sshpass123')
        dutA.cmd('crypto key generate userkey sshuser rsa')
        dutA.cmd('ssh server allow-users sshuser')
        dutA.mode('#')
        enable_ssh(self, dutA)

    def main(self):
        # ART 6000_link_check/library_6000.py lines 312-323
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        self.log("STEP 28: Record baseline DUT resource usage from the console (`show memory`, `show users`, and the platform's process/file-descriptor or system status output), then run many repeated cycles (e.g. 100) of: open an IPv6 SSH session, authenticate (mixing valid logins with deliberately failed ones), execute a CLI command, and disconnect. Re-read the same resource outputs after the final cycle.")

        def parse_mem_used(memOutput):
            m = re.search(r'Mem:\s+(\d+)\s+(\d+)\s+(\d+)', memOutput)
            if m:
                return int(m.group(2))
            return None

        sshServer = tb.ethA.get_ipv6_addr(2)
        validUser = 'sshuser'
        validPass = 'sshpass123'

        dutA.mode('#')
        dutA.cmd('clear log')
        dutA.cmd('clear exception log')

        baseline_memory = run_show_command(dutA, 'show memory')
        baseline_users = run_show_command(dutA, 'show users')
        baseline_ssh = run_show_command(dutA, 'show ssh')
        baseline_process = run_show_command(dutA, 'show process cpu')
        processSupported = not any(tok in baseline_process for tok in ('Invalid input', 'Unrecognized command', '% Unknown command'))
        self.log('BASELINE show memory:\n{}'.format(baseline_memory))
        self.log('BASELINE show users:\n{}'.format(baseline_users))
        self.log('BASELINE show ssh:\n{}'.format(baseline_ssh))
        if processSupported:
            self.log('BASELINE show process cpu:\n{}'.format(baseline_process))
        else:
            self.log('INFO: show process cpu not supported on this platform; process/file-descriptor checkpoint will be skipped')

        baselineMemUsed = parse_mem_used(baseline_memory)
        memSamples = []
        if baselineMemUsed is not None:
            memSamples.append(('baseline', baselineMemUsed))

        NUM_CYCLES = 30
        valid_cycle_failures = []
        invalid_cycle_failures = []
        valid_count = 0
        invalid_count = 0

        for i in range(NUM_CYCLES):
            if i % 4 == 3:
                # deliberately-failing cycle: wrong password
                invalid_count += 1
                ssh = paramiko.SSHClient()
                ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                authRejected = False
                try:
                    ssh.connect(sshServer, username=validUser, password='wrongpass{}'.format(i), timeout=10, banner_timeout=15)
                except paramiko.AuthenticationException:
                    authRejected = True
                except Exception as e:
                    authRejected = True
                    self.log('cycle {}: connect raised {} (treated as rejection)'.format(i, e))
                finally:
                    try:
                        ssh.close()
                    except Exception:
                        pass
                if not authRejected:
                    invalid_cycle_failures.append('cycle {}: bad-password login was NOT rejected'.format(i))
            else:
                valid_count += 1
                ssh = paramiko.SSHClient()
                ssh.set_missing_host_key_policy(paramiko.AutoAddPolicy())
                try:
                    ssh.connect(sshServer, username=validUser, password=validPass, timeout=10, banner_timeout=15)
                    (stdin, stdout, stderr) = ssh.exec_command('show ssh server')
                    cmdOutput = stdout.read().decode()
                    if 'SSH Server' not in cmdOutput or 'Enabled' not in cmdOutput:
                        valid_cycle_failures.append('cycle {}: unexpected command output: {}'.format(i, cmdOutput[:200]))
                except Exception as e:
                    valid_cycle_failures.append('cycle {}: valid login/cmd failed: {}'.format(i, e))
                finally:
                    try:
                        ssh.close()
                    except Exception:
                        pass

            if i % 10 == 9:
                sampleMemory = run_show_command(dutA, 'show memory')
                sampledUsed = parse_mem_used(sampleMemory)
                if sampledUsed is not None:
                    memSamples.append(('cycle {}'.format(i), sampledUsed))

        dutA.mode('#')
        responseStart = time.time()
        final_ssh = run_show_command(dutA, 'show ssh')
        responseElapsed = time.time() - responseStart
        final_memory = run_show_command(dutA, 'show memory')
        final_users = run_show_command(dutA, 'show users')
        final_log = run_show_command(dutA, 'show log')
        final_process = run_show_command(dutA, 'show process cpu') if processSupported else ''
        self.log('FINAL show ssh:\n{}'.format(final_ssh))
        self.log('FINAL show memory:\n{}'.format(final_memory))
        self.log('FINAL show log:\n{}'.format(final_log))
        if processSupported:
            self.log('FINAL show process cpu:\n{}'.format(final_process))

        finalMemUsed = parse_mem_used(final_memory)
        if finalMemUsed is not None:
            memSamples.append(('final', finalMemUsed))

        output = 'valid_count={}, invalid_count={}, valid_failures={}, invalid_failures={}, response_time={:.2f}s, mem_samples={}'.format(
            valid_count, invalid_count, len(valid_cycle_failures), len(invalid_cycle_failures), responseElapsed, memSamples)
        self.log('OBSERVED: {}'.format(output))

        if not valid_cycle_failures:
            self.passed('All {} valid SSH cycles authenticated and returned correct `show ssh server` output throughout the run'.format(valid_count))
        else:
            self.failed('{} of {} valid SSH cycles failed to authenticate/return expected output: {}'.format(
                len(valid_cycle_failures), valid_count, valid_cycle_failures[:3]))

        if not invalid_cycle_failures:
            self.passed('All {} deliberately-bad-password SSH attempts were rejected without granting access'.format(invalid_count))
        else:
            self.failed('{} of {} bad-password SSH attempts were NOT rejected: {}'.format(
                len(invalid_cycle_failures), invalid_count, invalid_cycle_failures[:3]))

        baselineSessionLines = [l for l in baseline_ssh.splitlines() if validUser in l]
        finalSessionLines = [l for l in final_ssh.splitlines() if validUser in l]
        if len(finalSessionLines) <= len(baselineSessionLines):
            self.passed('Active SSH session list for {} returned to baseline ({} sessions) after the last cycle, no orphaned sessions ({} sessions)'.format(
                validUser, len(baselineSessionLines), len(finalSessionLines)))
        else:
            self.failed('Active SSH session list for {} did NOT return to baseline: baseline {} sessions, final {} sessions'.format(
                validUser, len(baselineSessionLines), len(finalSessionLines)))

        crashMarkers = ['Exception information saved', 'core file', 'Segmentation fault', 'panic']
        foundCrash = [m for m in crashMarkers if m in final_log]
        if not foundCrash:
            self.passed('show log after the run contains no exception traces or crash records')
        else:
            self.failed('show log after the run contains crash/exception markers: {}'.format(foundCrash))

        if responseElapsed < 10:
            self.passed('DUT responded to `show ssh` at normal speed after the run ({:.2f}s)'.format(responseElapsed))
        else:
            self.failed('DUT took {:.2f}s to respond to `show ssh` after the run, slower than the 10s normal-speed threshold'.format(responseElapsed))

        if baselineMemUsed is None or finalMemUsed is None:
            self.failed('show memory did not contain a parsable "Mem:" used-KB field to compare against baseline (baseline: {}, final: {})'.format(
                baseline_memory[:200], final_memory[:200]))
        else:
            memGrowthKB = finalMemUsed - baselineMemUsed
            memThreshold = max(2048, baselineMemUsed * 0.10)
            if memGrowthKB <= memThreshold:
                self.passed('Used memory (Mem: used field) after {} cycles ({}kB) shows no monotonic accumulation vs baseline ({}kB); samples through the run: {}'.format(
                    NUM_CYCLES, finalMemUsed, baselineMemUsed, memSamples))
            else:
                self.failed('Used memory (Mem: used field) grew from {}kB to {}kB (+{}kB, threshold {}kB); samples through the run: {}, suggests accumulation'.format(
                    baselineMemUsed, finalMemUsed, memGrowthKB, memThreshold, memSamples))

        if processSupported:
            baselineProcCount = len(baseline_process.strip().splitlines())
            finalProcCount = len(final_process.strip().splitlines())
            if finalProcCount <= baselineProcCount + 2:
                self.passed('`show process cpu` line count after {} cycles ({}) shows no monotonic accumulation vs baseline ({})'.format(
                    NUM_CYCLES, finalProcCount, baselineProcCount))
            else:
                self.failed('`show process cpu` line count grew from {} to {} after {} cycles, suggests process/file-descriptor accumulation'.format(
                    baselineProcCount, finalProcCount, NUM_CYCLES))
        else:
            self.log('INFO: process/file-descriptor checkpoint skipped, `show process cpu` not supported on this platform')

    def tear_down(self):
        tb = self.testSet.tb
        dutA = self.testSet.dutA
        ethA = tb.ethA
        portA = dutA.portA
        peer = self.testSet.peer
        portPeer = dutA.portPeer
        portDut = peer.portDut
        stk_a = self.testSet.stk_a
        dutA.mode(')#')
        dutA.cmd('no ssh server allow-users sshuser')
        dutA.cmd('crypto key destroy userkey sshuser rsa')
        dutA.cmd('no user sshuser')
        dutA.cmd('no service ssh')
        dutA.cmd('crypto key destroy hostkey rsa')
        dutA.cmd('interface vlan1')
        dutA.cmd('no ipv6 address {}/{}'.format(tb.ethA.get_ipv6_addr(2), tb.ethA.ipv6globPrefix))
        dutA.mode('#')


